336	        public void completeOverloadingCheck(Overload o1,
337	                                             Overload o2,
338	                                             Collection<Overload> new_overloads,
339	                                             Environment within) {
340	
341	            //OverloadComparisonResult ocr = this;
342	
343	            List<FType> pl1 = o1.getParams();
344	            List<FType> pl2 = o2.getParams();
345	
346	            {
347	                l1 = pl1.size();
348	                l2 = pl2.size();
349	
350	                rest1 = (l1 > 0 && pl1.get(l1 - 1) instanceof FTypeRest);
351	                rest2 = (l2 > 0 && pl2.get(l2 - 1) instanceof FTypeRest);
352	
353	                // by construction, l1 is bigger.
354	                // (see sort order above)
355	                // possibilities
356	                // rest1 l2 can be no smaller than l1-1; iterate to l2
357	                // rest2 test out to l1
358	                // both  test out to l1
359	                // neither = required
360	
361	
362	                if (rest2) {
363	                    // both, rest2
364	                    min = l1;
365	                } else if (rest1) {
366	                    // rest1
367	                    if (l2 < l1 - 1) return;
368	                    min = l2;
369	                } else {
370	                    // neither
371	                    if (l1 != l2) return;
372	                    min = l1;
373	                }
374	
375	                //    if (!do_continue) {
376	
377	
378	                //                  int p1better = -1; // set to index where p1 is subtype
379	                //                  int p2better = -1; // set to index where p2 is subtype
380	
381	                //                  boolean distinct = false; // known to exclude
382	                //                  int unrelated = -1; // neither subtype nor exclude nor identical
383	                //                  boolean unequal = false;
384	                //                  boolean sawSymbolic1 = false;
385	                //                  boolean sawSymbolic2 = false;
386	                //                  int selfIndex = -1;
387	
388	                /* This is a hack for dealing with cases like
389	                *
390	  trait Bar[\A,nat n\]
391	      get():ZZ32 = n
392	  end
393	
394	  object Baz[\A,nat n\]() extends Bar[\A,n\]
395	  end
396	
397	  f[\A\](x:Bar[\A,17\]) = 20
398	  g[\A\](x:Baz[\A,17\]) = 21
399	  h[\A\](x:Bar[\A,17\]) = 22
400	  h[\A\](x:Baz[\A,17\]) = 23
401	
402	
403	
404	                */
405	                //                  boolean allObjInstance1 = true;
406	                //                  boolean allObjInstance2 = true;
407	
408	                exclDumpln("Checking exclusion of ", pl1, " and ", pl2, ":");
409	                for (int k = 0; k < min; k++) {
410	                    FType p1 = pl1.get(k);
411	                    FType p2 = k < l2 ? pl2.get(k) : pl2.get(l2 - 1);
412	                    exclDump(k, ": ", p1, " and ", p2, ", ", p1.getExtends(), " and ", p2.getExtends(), ", ");
413	
414	                    p1 = deRest(p1);
415	                    p2 = deRest(p2);
416	
417	                    if (p1 == p2 && !p1.isSymbolic() && !p2.isSymbolic()) {
418	                        exclDumpln("equal.");
419	                        continue;
420	                    }
421	
422	                    allObjInstance1 &= p1 instanceof FTypeObject;
423	                    allObjInstance2 &= p2 instanceof FTypeObject;
424	
425	                    unequal = true;
426	
427	                    if (o1.getSelfParameterIndex() == k && o1.getSelfParameterIndex() == o2.getSelfParameterIndex()) {
428	                        exclDumpln("self params.");
429	                        // ONLY set this when the self indices coincide -- otherwise, they obey the same rules.
430	                        selfIndex = k;
431	                        /*
432	                        * Somebody Else's Problem -- if self parameters are different,
433	                        * any problems will be flagged at the object level.
434	                        */
435	                        if (!p1.equals(p2)) distinct = true; // This seems wrong/unnecessary
436	                    }
437	
438	                    if ( o1.getFn().getFnName() instanceof Op &&
439	                         o2.getFn().getFnName() instanceof Op &&
440	                         ((Op)o1.getFn().getFnName()).getFixity() !=
441	                         ((Op)o2.getFn().getFnName()).getFixity() )
442	                        distinct = true;
443	
444	                    if (p1.excludesOther(p2)) {
445	                        exclDumpln("distinct.");
446	                        distinct = true;
447	                    } else {
448	
449	                        boolean local_unrelated = true;
450	                        // Check for subtype constraint.
451	                        boolean p1subp2 = p1.subtypeOf(p2);
452	                        boolean p2subp1 = p2.subtypeOf(p1);
453	                        if (p1subp2 && !p2subp1) {
454	                            p1better = k;
455	                            local_unrelated = false;
456	                            exclDumpln(" left better.");
457	                        } else if (p2subp1 && !p1subp2) {
458	                            p2better = k;
459	                            local_unrelated = false;
460	                            exclDumpln(" right better.");
461	                        } else if (selfIndex != k) {
462	                            if (p1.isSymbolic()) sawSymbolic1 = true;
463	
464	                            if (p2.isSymbolic()) sawSymbolic2 = true;
465	                        }
466	                        if (local_unrelated && unrelated == -1) {
467	                            // Here we check for self parameters!
468	                            if (selfIndex != k) {
469	                                unrelated = k;
470	                                exclDumpln("Unrelated.");
471	                            }
472	                        }
473	                    }
474	                }
475	
476	                distinct |= unequal && (allObjInstance1 || allObjInstance2);
477	            }
478	            //      }
479	
480	            if (!distinct) {
481	                if (p1better >= 0 && p2better >= 0) {
482	                    meetOk = meetExistsIn(o1, o2, new_overloads);
483	                } else {
484	                    FType r1 = o1.getFn().getRange();
485	                    FType r2 = o2.getFn().getRange();
486	                    if (p1better >= 0) {
487	                        // subtype rule applies
488	                        result1Subtype2Failure = !r1.subtypeOf(r2);
489	                    } else if (p2better >= 0) {
490	                        // subtype rule applies
491	                        result2Subtype1Failure = !r2.subtypeOf(r1);
492	                    }
493	                }
494	            }
495	
496	
497	            if (!distinct && !overloadOk()) {
498	                if (validOnDeclaredDomains(o1, o2, new_overloads)) return;
499	                if (unrelated != -1 && !sawSymbolic1 && !sawSymbolic2 && overlapCovered(o1, pl1, o2, pl2, new_overloads)) return;
500	            }
501	
502	            describeOverloadingFailure(o1, o2, within, pl1, pl2);
503	
504	            return;
505	        }
