507	        public boolean overloadOk() {
508	
509	            // exclusion is good.
510	            if (distinct) return true;
511	
512	            // non-ground types need exclusion
513	            if (sawSymbolic1 || sawSymbolic2 || unrelated != -1) {
514	                return false;
515	            }
516	
517	            // meet rule
518	            if (p1better >= 0 && p2better >= 0 && !meetOk) return false;
519	
520	            // neither is better, not a functional method
521	            if (p1better < 0 && p2better < 0 && selfIndex < 0) return false;
522	
523	            if (result1Subtype2Failure || result2Subtype1Failure) return false;
524	
525	            return true;
526	        }
