530	                                                Environment within,
531	                                                List<FType> pl1,
532	                                                List<FType> pl2) {
533	            if (distinct) return;
534	            //OverloadComparisonResult ocr = this;
535	            if (sawSymbolic1 || sawSymbolic2) {
536	                exclDumpSkip();
537	                String explanation;
538	                if (sawSymbolic1 && sawSymbolic2) explanation = errorMsg("\n", o1, " and\n", o2, " have parameters\n");
539	                else if (sawSymbolic1) explanation = errorMsg("\n", o1, " has a parameter\n");
540	                else explanation = errorMsg("\n", o2, " has a parameter\n");
541	                explanation =
542	                        explanation + "with generic type, at least one pair of parameters must have excluding types";
543	                error(o1, o2, within, explanation);
544	            }
545	
546	            if (unrelated != -1) {
547	                exclDumpSkip();
548	                String s1 = parameterName(unrelated, o1);
549	                String s2 = parameterName(unrelated, o2);
550	
551	                String explanation = errorMsg(Ordinal.ordinal(unrelated + 1),
552	                                              " parameters ",
553	                                              s1,
554	                                              ":",
555	                                              pl1,
556	                                              " and ",
557	                                              s2,
558	                                              ":",
559	                                              pl2,
560	                                              " are unrelated (neither subtype, excludes, nor equal) and no excluding pair is present");
561	                error(o1, o2, within, explanation);
562	            }
563	
564	            if (p1better >= 0 && p2better >= 0 && !meetOk) {
565	                exclDumpSkip();
566	                error(o1, o2, within, errorMsg("Overloading of\n\t(first) ",
567	                                               o1,
568	                                               " and\n\t(second) ",
569	                                               o2,
570	                                               " fails because\n\t",
571	                                               formatParameterComparison(p1better, o1, o2, "more"),
572	                                               " but\n\t",
573	                                               formatParameterComparison(p2better, o1, o2, "less")));
574	            }
575	            if (p1better < 0 && p2better < 0 && selfIndex < 0) {
576	                exclDumpSkip();
577	                String explanation = null;
578	                if (l1 == l2 && rest1 == rest2) {
579	                    if (unequal) explanation = errorMsg("Overloading of ",
580	                                                        o1,
581	                                                        " and ",
582	                                                        o2,
583	                                                        " fails because their parameter lists have potentially overlapping (non-excluding) types");
584	                    else explanation = errorMsg("Overloading of ",
585	                                                o1,
586	                                                " and ",
587	                                                o2,
588	                                                " fails because their parameter lists have the same types");
589	                } else explanation = errorMsg("Overloading of ",
590	                                              o1,
591	                                              " and ",
592	                                              o2,
593	                                              " fails because of ambiguity in overlapping rest (...) parameters");
594	                error(o1, o2, within, explanation);
595	            }
596	
597	            if (result1Subtype2Failure) {
598	                String explanation = errorMsg("Overloading of ",
599	                                              o1,
600	                                              " and ",
601	                                              o2,
602	                                              " fails because the first parameter list is a subtype of the second, but the first result is not a subtype of the second");
603	                // System.err.println("FAIL " + explanation);
604	                error(o1, o2, within, explanation);
605	            }
606	            if (result2Subtype1Failure) {
607	                String explanation = errorMsg("Overloading of ",
608	                                              o1,
609	                                              " and ",
610	                                              o2,
611	                                              " fails because the second parameter list is a subtype of the first, but the second result is not a subtype of the first");
612	                // System.err.println("FAIL " + explanation);
613	                error(o1, o2, within, explanation);
614	            }
615	
616	        }
