683	    /**
684	     * A pair of one own generic and one declaration without static
685	     * parameters that the parameter-by-parameter check refuses, read on the
686	     * two declared domains: valid when one lies strictly inside the other and
687	     * the inner one's return type is below the outer one's for every
688	     * instance of the generic, its type parameters standing for themselves;
689	     * or when neither lies inside the other and declarations below both
690	     * cover their overlap (genericOverlapCovered).  Pairs of two generics
691	     * keep that check.
692	     */
693	    static private boolean validOnDeclaredDomains(Overload o1, Overload o2, Collection<Overload> all) {
694	        SingleFcn f1 = o1.getFn();
695	        SingleFcn f2 = o2.getFn();
696	        Overload gen;
697	        Overload plain;
698	        if (ownGeneric(f1) && !(f2 instanceof GenericFunctionOrMethod)) {
699	            gen = o1;
700	            plain = o2;
701	        } else if (ownGeneric(f2) && !(f1 instanceof GenericFunctionOrMethod)) {
702	            gen = o2;
703	            plain = o1;
704	        } else {
705	            return false;
706	        }
707	        if (hasRest(gen.getParams()) || hasRest(plain.getParams())) return false;
708	        if (gen.getParams().size() != plain.getParams().size()) return false;
709	        try {
710	            SingleFcn g = gen.getFn();
711	            SingleFcn p = plain.getFn();
712	            boolean plainInside = instanceHolding(g, plain.getParams(), true) != null;
713	            boolean genInside = declaredBelow(g, null, p, p, true);
714	            if (plainInside && genInside) return false;
715	            if (plainInside) return p.getRange().subtypeOf(g.getRange());
716	            if (genInside) return g.getRange().subtypeOf(p.getRange());
717	            return genericOverlapCovered(gen, plain, all);
718	        }
719	        catch (FortressException ex) {
720	            return false;
721	        }
722	    }
