833	    /**
834	     * The overlap of the domains d1 of o1 and d2 of o2 is covered by
835	     * declarations of all without static parameters whose domains lie below
836	     * both: the overlap, position by position, is a union of parts, each part
837	     * an intersection of types (intersectionPieces), and every combination of
838	     * parts across the positions lies inside the domain of one such
839	     * declaration.  Each position of d1 is the types whose intersection it
840	     * holds, one type unless o1 is an own generic.  An empty overlap needs no
841	     * declaration.  A search that does not settle refuses.
842	     */
843	    static private boolean overlapCoveredBy(Overload o1, List<List<FType>> d1, Overload o2, List<FType> d2,
844	                                            Collection<Overload> all) {
845	        int n = d1.size();
846	        int[] steps = {OVERLAP_STEPS};
847	        List<List<Set<FType>>> parts = new ArrayList<List<Set<FType>>>(n);
848	        long combinations = 1;
849	        for (int k = 0; k < n; k++) {
850	            List<FType> both = new ArrayList<FType>(d1.get(k));
851	            both.add(d2.get(k));
852	            List<Set<FType>> pk = intersectionPieces(both, new HashSet<List<FType>>(), steps);
853	            if (pk == null) return false;
854	            if (pk.isEmpty()) return true;
855	            parts.add(pk);
856	            combinations *= pk.size();
857	            if (combinations > OVERLAP_PARTS) return false;
858	        }
859	        List<List<FType>> covers = new ArrayList<List<FType>>();
860	        for (Overload o : all) {
861	            if (o == o1 || o == o2 || o instanceof Overload.MethodOverload) continue;
862	            SingleFcn f = o.getFn();
863	            if (f instanceof GenericFunctionOrMethod) continue;
864	            List<FType> d = o.getParams();
865	            if (d.size() != n || hasRest(d)) continue;
866	            FType dt = FTypeTuple.make(d);
867	            try {
868	                if (!dt.subtypeOf(FTypeTuple.make(d2))) continue;
869	                if (o1.getFn() instanceof GenericFunctionOrMethod) {
870	                    if (instanceHolding(o1.getFn(), d, true) == null) continue;
871	                } else {
872	                    List<FType> d1Types = new ArrayList<FType>(n);
873	                    for (List<FType> ts : d1) d1Types.add(ts.get(0));
874	                    if (!dt.subtypeOf(FTypeTuple.make(d1Types))) continue;
875	                }
876	            }
877	            catch (FortressException ex) {
878	                continue;
879	            }
880	            covers.add(d);
881	        }
882	        int[] index = new int[n];
883	        while (true) {
884	            boolean covered = false;
885	            for (List<FType> c : covers) {
886	                boolean inside = true;
887	                for (int k = 0; inside && k < n; k++) {
888	                    inside = someBelow(parts.get(k).get(index[k]), c.get(k));
889	                }
890	                if (inside) {
891	                    covered = true;
892	                    break;
893	                }
894	            }
895	            if (!covered) return false;
896	            int k = 0;
897	            while (k < n && ++index[k] == parts.get(k).size()) {
898	                index[k] = 0;
899	                k++;
900	            }
901	            if (k == n) return true;
902	        }
903	    }
